<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{MenuItem,Page};use Illuminate\Http\Request;class MenuController extends Controller{public function index(){return view('admin.menus.index',['items'=>MenuItem::with('page')->orderBy('location')->orderBy('sort')->get(),'pages'=>Page::orderBy('title')->get()]);}public function create(){return $this->form(new MenuItem);}public function store(Request $r){MenuItem::create($this->data($r));return redirect()->route('admin.menus.index')->with('ok','Пункт меню создан');}public function edit(MenuItem $menu){return $this->form($menu);}public function update(Request $r,MenuItem $menu){$menu->update($this->data($r,$menu));return redirect()->route('admin.menus.index')->with('ok','Меню обновлено');}public function destroy(MenuItem $menu){$menu->delete();return back();}private function form($item){return view('admin.menus.form',['item'=>$item,'parents'=>MenuItem::where('id','!=',$item->id??0)->orderBy('title')->get(),'pages'=>Page::orderBy('title')->get()]);}private function data(Request $r,?MenuItem $item=null){$d=$r->validate(['title'=>'required|max:255','parent_id'=>'nullable|exists:menu_items,id','page_id'=>'nullable|exists:pages,id','url'=>'nullable|max:2048','location'=>'required|in:main,footer,service','target'=>'required|in:_self,_blank','sort'=>'nullable|integer']);if($item&&$d['parent_id']??false){abort_if((int)$d['parent_id']===$item->id,422,'Пункт не может быть родителем самому себе.');}$d['is_active']=$r->boolean('is_active');return $d;}}